using System;
using System.Data;
using System.Text;
using System.Web.UI.WebControls;

namespace InformationWeb.Controls.Dorm
{
    /// <summary>
    /// Dựng cây Khu vực / Phòng / Giường giống UDormBedTree (WinForms).
    /// </summary>
    public static class DormBedTreeHelper
    {
        public const string NodeValuePrefixArea = "A";
        public const string NodeValuePrefixDorm = "D";
        public const string NodeValuePrefixBed = "B";

        public static DataTable BuildTreeTable(DataTable dtbDormBed)
        {
            if (dtbDormBed == null)
            {
                return null;
            }

            DataTable dtbTree = dtbDormBed.Clone();
            dtbTree.Columns.Add("ID", typeof(string));
            dtbTree.Columns.Add("Title", typeof(string));
            dtbTree.Columns.Add("ParentID", typeof(string));
            dtbTree.Columns.Add("NodeValue", typeof(string));

            string strAreaID = string.Empty;
            string strDormID = string.Empty;

            foreach (DataRow drw in dtbDormBed.Rows)
            {
                string strTemp = drw["AreaID"].ToString();
                if (strAreaID != strTemp)
                {
                    strAreaID = strTemp;
                    DataRow drwNew = dtbTree.NewRow();
                    drwNew["ID"] = strAreaID;
                    drwNew["Title"] = drw["AreaName"];
                    drwNew["ParentID"] = DBNull.Value;
                    drwNew["AreaID"] = strAreaID;
                    drwNew["NodeValue"] = BuildNodeValue(NodeValuePrefixArea, strAreaID, null, null);
                    dtbTree.Rows.Add(drwNew);
                }

                strTemp = drw["DormID"].ToString();
                if (strDormID != strTemp)
                {
                    strDormID = strTemp;
                    DataRow drwNew = dtbTree.NewRow();
                    string strDormNodeId = strAreaID + "_" + strDormID;
                    drwNew["ID"] = strDormNodeId;
                    drwNew["Title"] = drw["DormName"];
                    drwNew["ParentID"] = strAreaID;
                    drwNew["AreaID"] = strAreaID;
                    drwNew["DormID"] = strDormID;
                    drwNew["NodeValue"] = BuildNodeValue(NodeValuePrefixDorm, strAreaID, strDormID, null);
                    dtbTree.Rows.Add(drwNew);
                }

                DataRow drwBed = dtbTree.NewRow();
                string strBedNodeId = strAreaID + "_" + strDormID + "_" + drw["DormBedID"].ToString();
                drwBed["ID"] = strBedNodeId;
                drwBed["Title"] = drw["DormBedName"];
                drwBed["ParentID"] = strAreaID + "_" + strDormID;
                drwBed["AreaID"] = strAreaID;
                drwBed["DormID"] = strDormID;
                drwBed["DormBedID"] = drw["DormBedID"];
                drwBed["NodeValue"] = BuildNodeValue(NodeValuePrefixBed, strAreaID, strDormID, drw["DormBedID"].ToString());
                dtbTree.Rows.Add(drwBed);
            }

            return dtbTree;
        }

        public static string BuildNodeValue(string prefix, string areaId, string dormId, string dormBedId)
        {
            return string.Format("{0}|{1}|{2}|{3}",
                prefix,
                areaId ?? string.Empty,
                dormId ?? string.Empty,
                dormBedId ?? string.Empty);
        }

        public static void ParseNodeValue(string nodeValue, out string areaId, out string dormId, out string dormBedId)
        {
            areaId = null;
            dormId = null;
            dormBedId = null;

            if (string.IsNullOrEmpty(nodeValue))
            {
                return;
            }

            string[] parts = nodeValue.Split('|');
            if (parts.Length < 4)
            {
                return;
            }

            if (parts[1].Length > 0)
            {
                areaId = parts[1];
            }
            if (parts[2].Length > 0)
            {
                dormId = parts[2];
            }
            if (parts[3].Length > 0)
            {
                dormBedId = parts[3];
            }
        }

        public static void BindTreeView(TreeView treeView, DataTable dtbTree)
        {
            treeView.Nodes.Clear();
            if (dtbTree == null)
            {
                return;
            }

            foreach (DataRow drw in dtbTree.Rows)
            {
                if (drw["ParentID"] == DBNull.Value || drw["ParentID"].ToString().Length == 0)
                {
                    TreeNode node = CreateTreeNode(drw);
                    treeView.Nodes.Add(node);
                    AppendChildNodes(node, dtbTree);
                }
            }
        }

        private static void AppendChildNodes(TreeNode parentNode, DataTable dtbTree)
        {
            string strParentId = parentNode.Value;
            foreach (DataRow drw in dtbTree.Rows)
            {
                if (drw["ParentID"] == DBNull.Value)
                {
                    continue;
                }
                if (drw["ParentID"].ToString() != GetRowNodeKey(drw["ParentID"]))
                {
                    continue;
                }

                TreeNode child = CreateTreeNode(drw);
                parentNode.ChildNodes.Add(child);
                AppendChildNodes(child, dtbTree);
            }
        }

        private static TreeNode CreateTreeNode(DataRow drw)
        {
            TreeNode node = new TreeNode();
            node.Text = drw["Title"].ToString();
            node.Value = drw["NodeValue"].ToString();
            node.SelectAction = TreeNodeSelectAction.SelectExpand;
            return node;
        }

        private static string GetRowNodeKey(object parentId)
        {
            if (parentId == null || parentId == DBNull.Value)
            {
                return string.Empty;
            }
            return parentId.ToString();
        }

        public static TreeNode FindNodeByDormId(TreeView treeView, string dormId)
        {
            if (treeView == null || string.IsNullOrEmpty(dormId))
            {
                return null;
            }

            foreach (TreeNode node in treeView.Nodes)
            {
                TreeNode found = FindNodeByDormIdRecursive(node, dormId);
                if (found != null)
                {
                    return found;
                }
            }

            return null;
        }

        private static TreeNode FindNodeByDormIdRecursive(TreeNode node, string dormId)
        {
            if (node.Value != null && node.Value.StartsWith(NodeValuePrefixDorm + "|"))
            {
                string areaId;
                string nodeDormId;
                string dormBedId;
                ParseNodeValue(node.Value, out areaId, out nodeDormId, out dormBedId);
                if (string.Equals(nodeDormId, dormId, StringComparison.OrdinalIgnoreCase))
                {
                    return node;
                }
            }

            foreach (TreeNode child in node.ChildNodes)
            {
                TreeNode found = FindNodeByDormIdRecursive(child, dormId);
                if (found != null)
                {
                    return found;
                }
            }

            return null;
        }

        public static void ExpandParentChain(TreeNode node)
        {
            TreeNode current = node;
            while (current != null)
            {
                current.Expanded = true;
                current = current.Parent;
            }
        }
    }
}

using System;
using System.Data;
using System.Globalization;
using System.Web.UI;
using System.Web.UI.WebControls;
using DCore;
using SimsObject;
using WebGlobal;

namespace InformationWeb.Controls.Dorm
{
    public partial class DormBedView : ControlBase
    {
        private const string StoreSearchBed = "SIM_DormBed_SEARCH";

        private string SelectedAreaID
        {
            get
            {
                if (ViewState["SelectedAreaID"] != null)
                {
                    return ViewState["SelectedAreaID"].ToString();
                }
                return null;
            }
            set { ViewState["SelectedAreaID"] = value; }
        }

        private string SelectedDormID
        {
            get
            {
                if (ViewState["SelectedDormID"] != null)
                {
                    return ViewState["SelectedDormID"].ToString();
                }
                return null;
            }
            set { ViewState["SelectedDormID"] = value; }
        }

        protected void Page_Load(object sender, EventArgs e)
        {
            if (Session[Globals.USER] == null)
            {
                MsgBox.ShowError("Bạn chưa đăng nhập hệ thống!");
                return;
            }

            if (!IsPostBack)
            {
                LoadTreeData();
            }
        }

        protected string FormatDate(object value)
        {
            if (value == null || value == DBNull.Value)
            {
                return string.Empty;
            }

            DateTime dtm;
            if (value is DateTime)
            {
                dtm = (DateTime)value;
            }
            else if (!DateTime.TryParse(value.ToString(), out dtm))
            {
                return string.Empty;
            }

            return dtm.ToString("dd/MM/yyyy", CultureInfo.InvariantCulture);
        }

        private void LoadTreeData()
        {
            SIM_DormBed objDormBed = new SIM_DormBed();
            DataTable dtbDormBed = objDormBed.GetDataTable(StoreSearchBed, "@IsActived", 1);
            if (dtbDormBed == null)
            {
                MsgBox.ShowError("Việc tải danh mục phòng bị lỗi!");
                return;
            }

            DataTable dtbTree = DormBedTreeHelper.BuildTreeTable(dtbDormBed);
            ViewState["DormBedTree"] = dtbTree;
            DormBedTreeHelper.BindTreeView(tvDormBed, dtbTree);

            if (tvDormBed.Nodes.Count > 0)
            {
                tvDormBed.Nodes[0].Selected = true;
                tvDormBed.Nodes[0].Expand();
                ApplySelectionFromNode(tvDormBed.Nodes[0]);
            }
            else
            {
                BindEmptyCards();
            }
        }

        private void LoadBedCards()
        {
            if (string.IsNullOrEmpty(SelectedAreaID) && string.IsNullOrEmpty(SelectedDormID))
            {
                BindEmptyCards();
                return;
            }

            SIM_DormBed obj = new SIM_DormBed();
            DataTable dtbDormBed = obj.SearchCurrentInfo(
                "@AreaID", SelectedAreaID,
                "@DormID", SelectedDormID);

            if (dtbDormBed == null)
            {
                MsgBox.ShowError("Việc tải thông tin bị lỗi!");
                return;
            }

            rptBedCards.DataSource = dtbDormBed;
            rptBedCards.DataBind();
            pnlEmpty.Visible = dtbDormBed.Rows.Count == 0;
            lblSelectionHint.Text = BuildSelectionHint();
        }

        private string BuildSelectionHint()
        {
            if (!string.IsNullOrEmpty(SelectedDormID))
            {
                return string.Format("Đang xem phòng: <strong>{0}</strong>", SelectedDormID);
            }
            if (!string.IsNullOrEmpty(SelectedAreaID))
            {
                return string.Format("Đang xem khu vực: <strong>{0}</strong>", SelectedAreaID);
            }
            return string.Empty;
        }

        private void BindEmptyCards()
        {
            rptBedCards.DataSource = null;
            rptBedCards.DataBind();
            pnlEmpty.Visible = true;
            lblSelectionHint.Text = string.Empty;
        }

        private void ApplySelectionFromNode(TreeNode node)
        {
            if (node == null)
            {
                BindEmptyCards();
                return;
            }

            string areaId;
            string dormId;
            string dormBedId;
            DormBedTreeHelper.ParseNodeValue(node.Value, out areaId, out dormId, out dormBedId);

            SelectedAreaID = areaId;
            SelectedDormID = dormId;
            LoadBedCards();
        }

        protected void tvDormBed_SelectedNodeChanged(object sender, EventArgs e)
        {
            ApplySelectionFromNode(tvDormBed.SelectedNode);
        }

        protected void btnFind_Click(object sender, EventArgs e)
        {
            string strDormId = txtDormID.Text.Trim();
            if (strDormId.Length == 0)
            {
                return;
            }

            TreeNode nodeFound = DormBedTreeHelper.FindNodeByDormId(tvDormBed, strDormId);
            if (nodeFound == null)
            {
                MsgBox.ShowWarning("Không tìm thấy phòng với mã đã nhập.");
                return;
            }

            DormBedTreeHelper.ExpandParentChain(nodeFound);
            nodeFound.Selected = true;
            ApplySelectionFromNode(nodeFound);
        }

        protected void btnReloadTree_Click(object sender, EventArgs e)
        {
            LoadTreeData();
        }
    }
}

