/* Đăng ký phòng KTX — layout tree + card (tương tự frmDormBedView) */
.dorm-bed-wrap {
    --dorm-bed-accent: #1e4d8c;
    --dorm-bed-card-border: #c5d4e8;
    --dorm-bed-caption-bg: #e8eef7;
}

.dorm-bed-page-title {
    color: var(--dorm-bed-accent);
    font-weight: 700;
}

.dorm-bed-panel-header {
    background: var(--dorm-bed-caption-bg);
    color: var(--dorm-bed-accent);
    font-weight: 600;
    border-bottom: 1px solid var(--dorm-bed-card-border);
}

.dorm-bed-tree-panel .card-body {
    min-height: 420px;
}

.dorm-bed-tree-scroll {
    max-height: calc(100vh - 280px);
    overflow: auto;
    border: 1px solid #e9ecef;
    border-radius: 0.375rem;
    padding: 0.35rem 0.5rem;
    background: #fff;
}

.dorm-bed-tree a {
    color: #333;
    text-decoration: none;
    font-size: 0.9rem;
}

.dorm-bed-tree a:hover {
    color: var(--dorm-bed-accent);
}

.dorm-bed-btn-find {
    background: var(--dorm-bed-accent);
    color: #fff;
    border: none;
}

.dorm-bed-btn-find:hover {
    background: #163a6a;
    color: #fff;
}

.dorm-bed-card-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 1.25rem;
}

.dorm-bed-card {
    border: 1px solid var(--dorm-bed-card-border);
    border-radius: 0.5rem;
    background: #fff;
    box-shadow: 0 1px 3px rgba(30, 77, 140, 0.08);
    overflow: hidden;
}

.dorm-bed-card-caption {
    background: var(--dorm-bed-caption-bg);
    color: var(--dorm-bed-accent);
    font-weight: 700;
    text-align: center;
    padding: 0.45rem 0.5rem;
    letter-spacing: 0.04em;
    border-bottom: 1px solid var(--dorm-bed-card-border);
}

.dorm-bed-card-fields {
    margin: 0;
    padding: 0.65rem 0.75rem 0.75rem;
}

.dorm-bed-field {
    display: grid;
    grid-template-columns: 38% 1fr;
    gap: 0.35rem 0.5rem;
    margin-bottom: 0.35rem;
    font-size: 0.8125rem;
    line-height: 1.35;
}

.dorm-bed-field dt {
    margin: 0;
    font-weight: 600;
    color: #555;
}

.dorm-bed-field dd {
    margin: 0;
    font-weight: 700;
    color: #222;
    word-break: break-word;
}

.dorm-bed-lbl {
    font-size: 0.8125rem;
    font-weight: 600;
    color: #555;
}

@media (max-width: 767.98px) {
    .dorm-bed-tree-scroll {
        max-height: 280px;
    }
}

(function () {
    function initDormBedView() {
        var txtDorm = document.querySelector('.dorm-bed-search input[type="text"]');
        if (txtDorm) {
            txtDorm.addEventListener('keydown', function (e) {
                if (e.keyCode === 13) {
                    e.preventDefault();
                    var btn = document.querySelector('.dorm-bed-btn-find');
                    if (btn) {
                        btn.click();
                    }
                }
            });
        }

        document.addEventListener('keydown', function (e) {
            if (e.keyCode === 116) {
                var reload = document.querySelector('[id$="btnReloadTree"]');
                if (reload && reload.offsetParent !== null) {
                    e.preventDefault();
                    reload.click();
                }
            }
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initDormBedView);
    } else {
        initDormBedView();
    }
})();

