using System;
using System.Data;
using System.Web.UI.WebControls;

namespace InformationWeb.Controls.Dorm
{
    public static class DormWebLookup
    {
        public static void BindTable(DropDownList ddl, DataTable table, string valueField, string textField)
        {
            if (ddl == null)
            {
                return;
            }

            ddl.Items.Clear();
            if (table == null)
            {
                ddl.Items.Add(new ListItem("-- Chọn --", ""));
                return;
            }

            ddl.DataSource = table;
            ddl.DataValueField = valueField;
            ddl.DataTextField = textField;
            ddl.DataBind();
            ddl.Items.Insert(0, new ListItem("-- Chọn --", ""));
        }

        public static void SelectValue(DropDownList ddl, string value)
        {
            if (ddl == null)
            {
                return;
            }

            string val = value == null ? string.Empty : value.Trim();
            if (val.Length == 0)
            {
                if (ddl.Items.Count > 0)
                {
                    ddl.SelectedIndex = 0;
                }
                return;
            }

            ListItem item = ddl.Items.FindByValue(val);
            if (item != null)
            {
                ddl.ClearSelection();
                item.Selected = true;
            }
        }
    }
}

