namespace InformationWeb.Controls.Dorm
{
    public partial class RegisterDormEdit : ControlBase
    {
        public const string PERMISSION_ADD = "SIM_RegisterDorm_Add";
        public const string PERMISSION_EDIT = "SIM_RegisterDorm_Edit";

        public event EventHandler DataSaved;

        private SIM_RegisterDorm itemRegisterDormEditing = new SIM_RegisterDorm();

        protected void Page_Load(object sender, EventArgs e)
        {
            RegisterClientScript();

            if (!IsPostBack)
            {
                LoadAreaDropdown();
                ApplyRegisterTypeUi();
            }

            uSelectStudent.ItemSelected += new Student.Select.ItemSelectedDelegate(uSelectStudent_ItemSelected);
        }

        public void OpenForBed(string dormBedId, long? registerDormId, string studentCode, string fullName)
        {
            if (!IsPostBack)
            {
                LoadAreaDropdown();
            }

            ClearForm(false);
            hidOriginalDormBedID.Value = dormBedId ?? string.Empty;

            if (registerDormId != null && registerDormId.Value > 0)
            {
                hidRegisterDormID.Value = registerDormId.Value.ToString();
                LoadRegisterRecord(registerDormId.Value, dormBedId);
            }
            else
            {
                hidRegisterDormID.Value = string.Empty;
                if (!string.IsNullOrEmpty(dormBedId))
                {
                    SelectBedCascade(dormBedId);
                }
                if (!string.IsNullOrEmpty(studentCode) || !string.IsNullOrEmpty(fullName))
                {
                    txtStudentDisplay.Text = string.Format("{0} - {1}", studentCode ?? string.Empty, fullName ?? string.Empty).Trim(' ', '-');
                }
            }

            CheckSavePermission();
            ScheduleOpenModalAfterUpdate();
            udpAll.Update();
        }

        protected void btnPickStudent_Click(object sender, EventArgs e)
        {
            uSelectStudent.ShowPopup();
        }

        protected void ddlArea_SelectedIndexChanged(object sender, EventArgs e)
        {
            LoadDormDropdown(ddlArea.SelectedValue);
            ddlDormBed.Items.Clear();
            ddlDormBed.Items.Add(new ListItem("-- Chọn --", ""));
        }

        protected void ddlDorm_SelectedIndexChanged(object sender, EventArgs e)
        {
            LoadDormBedDropdown(ddlDorm.SelectedValue);
        }

        protected void rdoRegisterType_CheckedChanged(object sender, EventArgs e)
        {
            ApplyRegisterTypeUi();
        }

        protected void btnReset_Click(object sender, EventArgs e)
        {
            string bedId = ddlDormBed.SelectedValue;
            ClearForm(true);
            if (!string.IsNullOrEmpty(bedId))
            {
                SelectBedCascade(bedId);
            }
            udpAll.Update();
        }

        protected void btnSave_Click(object sender, EventArgs e)
        {
            if (!IsValidEditForm())
            {
                return;
            }

            if (SaveData())
            {
                if (DataSaved != null)
                {
                    DataSaved(this, EventArgs.Empty);
                }

                if (chkAddMore.Checked)
                {
                    string bedId = ddlDormBed.SelectedValue;
                    ClearForm(true);
                    if (!string.IsNullOrEmpty(bedId))
                    {
                        SelectBedCascade(bedId);
                    }
                    ScheduleOpenModalAfterUpdate();
                }
                else
                {
                    ScheduleHideModalAfterUpdate();
                }

                udpAll.Update();
            }
        }

        private void uSelectStudent_ItemSelected(object value, object caption)
        {
            if (value == null)
            {
                return;
            }

            long lngStudentId;
            if (!long.TryParse(value.ToString(), out lngStudentId))
            {
                return;
            }

