        private bool IsValidEditForm()
        {
            long lngStudentId;
            if (!long.TryParse(hidStudentID.Value, out lngStudentId) || lngStudentId <= 0)
            {
                MsgBox.ShowWarning("Bạn phải chọn sinh viên!");
                return false;
            }

            if (string.IsNullOrEmpty(ddlArea.SelectedValue)
                || string.IsNullOrEmpty(ddlDorm.SelectedValue)
                || string.IsNullOrEmpty(ddlDormBed.SelectedValue))
            {
                MsgBox.ShowWarning("Bạn phải chọn đầy đủ khu, phòng và giường!");
                return false;
            }

            DateTime dtmStart;
            if (!TryParseDate(txtStartDate.Text, out dtmStart))
            {
                MsgBox.ShowWarning("Bạn phải chọn từ ngày hợp lệ (dd/MM/yyyy)!");
                return false;
            }

            DateTime dtmEnd = dtmStart;
            if (rdoPeriodRegister.Checked)
            {
                if (!TryParseDate(txtEndDate.Text, out dtmEnd))
                {
                    MsgBox.ShowWarning("Bạn phải chọn đến ngày hợp lệ (dd/MM/yyyy)!");
                    return false;
                }
            }
            else
            {
                int intMonths;
                if (!int.TryParse(txtMonth.Text.Trim(), out intMonths) || intMonths <= 0)
                {
                    MsgBox.ShowWarning("Bạn phải nhập số tháng hợp lệ!");
                    return false;
                }
                dtmEnd = dtmStart.AddMonths(intMonths);
            }

            string strOriginalBed = hidOriginalDormBedID.Value ?? string.Empty;
            string strNewBed = ddlDormBed.SelectedValue;
            if (strOriginalBed != strNewBed)
            {
                SIM_DormBed obj = new SIM_DormBed();
                DataTable dtb = obj.SearchCurrentInfo("@DormBedID", strNewBed, "@IsActived", 1);
                if (dtb != null && dtb.Rows.Count > 0)
                {
                    DataRow drw = dtb.Rows[0];
                    if (drw["StudentID"] != DBNull.Value && drw["StudentID"].ToString() != string.Empty)
                    {
                        MsgBox.ShowWarning(string.Format("Giường này đang được đăng ký bởi sinh viên '{0} - {1}'",
                            drw["StudentCode"], drw["Fullname"]));
                        return false;
                    }
                }
            }

            return true;
        }

        private bool SaveData()
        {
            long? registerId = null;
            long lngParsed;
            if (long.TryParse(hidRegisterDormID.Value, out lngParsed) && lngParsed > 0)
            {
                registerId = lngParsed;
            }

            long lngStudentId = long.Parse(hidStudentID.Value);
            DateTime dtmStart;
            TryParseDate(txtStartDate.Text, out dtmStart);
            DateTime dtmEnd;
            if (rdoPeriodRegister.Checked)
            {
                TryParseDate(txtEndDate.Text, out dtmEnd);
            }
            else
            {
                int intMonths = int.Parse(txtMonth.Text.Trim());
                dtmEnd = dtmStart.AddMonths(intMonths);
            }

            itemRegisterDormEditing = new SIM_RegisterDorm();
            if (registerId != null)
            {
                itemRegisterDormEditing.RegisterDormID = registerId;
                if (!itemRegisterDormEditing.Get())
                {
                    MsgBox.ShowError("Việc lấy thông tin bị lỗi!");
                    return false;
                }
            }

            itemRegisterDormEditing.StudentID = lngStudentId;
            itemRegisterDormEditing.DormBedID = ddlDormBed.SelectedValue;
            itemRegisterDormEditing.RegisterDormType = rdoPeriodRegister.Checked ? 1 : 2;
            itemRegisterDormEditing.StartDate = dtmStart;
            itemRegisterDormEditing.EndDate = dtmEnd;
            itemRegisterDormEditing.IsHeader = chkIsHeader.Checked;
            itemRegisterDormEditing.IsLeft = chkIsLeft.Checked;
            itemRegisterDormEditing.Description = txtDescription.Text.Trim();

            itemRegisterDormEditing.BeginTransaction();
            if (registerId == null)
            {
                itemRegisterDormEditing.CreatedUser = User.UserName;
                if (!itemRegisterDormEditing.Add())
                {
                    MsgBox.ShowError("Việc lưu bị lỗi!");
                    return false;
                }
            }
            else
            {
                itemRegisterDormEditing.UpdatedUser = User.UserName;
                if (!itemRegisterDormEditing.Update())
                {
                    MsgBox.ShowError("Việc lưu bị lỗi!");
                    return false;
                }
            }

            SIM_Student objStudent = new SIM_Student();
            objStudent.StudentID = itemRegisterDormEditing.StudentID;
            objStudent.CurrentDormID = ddlDorm.SelectedValue;
            objStudent.IsStayingDorm = !chkIsLeft.Checked;
            objStudent.UpdatedUser = User.UserName;
            objStudent.IDB = itemRegisterDormEditing.IDB;
            if (!objStudent.Update_RegisterDorm())
            {
                MsgBox.ShowError("Việc cập nhật thông tin phòng bị lỗi!");
                return false;
            }

            itemRegisterDormEditing.CommitTransaction();

            hidRegisterDormID.Value = itemRegisterDormEditing.RegisterDormID != null
                ? itemRegisterDormEditing.RegisterDormID.Value.ToString()
                : string.Empty;
            txtRegisterDormID.Text = hidRegisterDormID.Value;
            hidOriginalDormBedID.Value = ddlDormBed.SelectedValue;

            MsgBox.ShowSuccess("Lưu đăng ký thành công.");
            return true;
        }

